button_iconcycler.script:
function onValueChanged()
  	updateRank();
end
function updateRank()
	local sAction = getStringValue();
	if sAction == "officer" then
		window.npc_rank.setValue("3");
	elseif sAction == "member" then
		window.npc_rank.setValue("2");
	else
		window.npc_rank.setValue("1");
	end
end

stringfield.script:
				function onInit()
					window.rankIconCycler.updateRank();	    
				  	local sRank = getValue();
					if sRank == nil or sRank == "" then
					  	sRank = "follower";  -- default to follower
						setValue("1");
					elseif sRank == "officer" then
						setValue("3");
					elseif sRank == "member" then
					  	setValue("2");
					end
					sf.DebugOut("npc_rank onInit: " .. getValue() .. " (" .. sRank .. ")");
					updateWindowFrame();
				end
				function onValueChanged()
					updateWindowFrame();
				end
				function updateWindowFrame()
					local sAction = getValue();
					sf.DebugOut("updateFrame: " .. sAction);

				  if sAction == "3" then
				    window.setFrame("ctentrybox_friend"); 	-- officer
					elseif sAction == "2" then
						window.setFrame("ctentrybox_neutral"); 	-- member
					else
						window.setFrame("ctentrybox_foe"); 	-- follower
					end
				end

buttoncontrol.script:
				function onInit()					
				  	local sName = window.npc_name.getValue();
					if sName == "" or sName == nil then
					  popup();
					end
				end
        		function onButtonPress()
				  popup();
				end
				function popup()
					local sDBnode = window.getDatabaseNode();
					Interface.openWindow("popup_npcs", sDBnode);
				end
